const img=(id,w=600,h=500)=>`https://images.unsplash.com/${id}?auto=format&fit=crop&w=${w}&h=${h}&q=85`;
const people=[
 {name:'Maya Chen',handle:'mayainmotion',pic:img('photo-1531123897727-8f129e1688ce',100,100),place:'Lisbon, Portugal'},
 {name:'Theo Brooks',handle:'theobrooks',pic:img('photo-1500648767791-00dcc994a43e',100,100),place:'Brooklyn, NY'},
 {name:'Nina Flores',handle:'ninaflores',pic:img('photo-1534528741775-53994a69daeb',100,100),place:'Mexico City'},
 {name:'Oliver Park',handle:'oliverpark',pic:img('photo-1506794778202-cad84cf45f1d',100,100),place:'Seoul, Korea'},
 {name:'Amara Okafor',handle:'amara.o',pic:img('photo-1534751516642-a1af1ef26a56',100,100),place:'Accra, Ghana'},
 {name:'Luca Moretti',handle:'lucamoretti',pic:img('photo-1507003211169-0a1dd7228f2d',100,100),place:'Milan, Italy'}
