const me={name:'Alex Morgan',handle:'alexmorgan',pic:img('photo-1534528741775-53994a69daeb',100,100),bio:'Collecting little moments 🌿 | design, slow travel & good coffee',place:'Portland, OR'};
const seedPosts=[
 {id:'p1',author:people[0],text:'A slow morning, a warm pastel de nata, and absolutely nowhere to be. Lisbon, you have my whole heart ☀️',image:img('photo-1470252649378-9c29740c9fa8',1000,760),likes:248,comments:[{by:people[1],text:'Adding this to my someday list ✨',likes:12},{by:people[2],text:'That light is unreal!',likes:4}],time:'18 min',sample:true},
 {id:'p2',author:people[1],text:'Tiny reminder: you don’t have to have it all figured out to take the next step. 🌱',image:null,likes:87,comments:[{by:people[4],text:'Needed to hear this today.',likes:8}],time:'1 hr',sample:true},
 {id:'p3',author:people[3],text:'The city before it wakes up. Just me, my camera, and the last of the blue hour.',image:img('photo-1519501025264-65ba15a82390',1000,760),likes:512,comments:[{by:people[0],text:'The colors! 😍',likes:16}],time:'3 hr',sample:true},
 {id:'p4',author:people[4],text:'Sunday table, extra chairs, and enough jollof for everyone. That’s the whole plan. ❤️',image:img('photo-1547592180-85f173990554',1000,760),likes:174,comments:[],time:'5 hr',sample:true}
