const state={page:'home',theme:localStorage.getItem('hnm-theme')||'light',posts:JSON.parse(localStorage.getItem('hnm-posts')||'null')||seedPosts,following:JSON.parse(localStorage.getItem('hnm-following')||'null')||[people[0].handle,people[2].handle],notifications:JSON.parse(localStorage.getItem('hnm-notifs')||'null')||[],commentsPost:null,profileTab:'posts',messageTab:'general',messages:JSON.parse(localStorage.getItem('hnm-messages')||'null')||{general:[{by:'Maya Chen',text:'Good morning, Hnmgram ☀️',time:'9:14'},{by:'Theo Brooks',text:'Anyone have a favorite tiny coffee shop in Lisbon?',time:'9:20'}]},channels:JSON.parse(localStorage.getItem('hnm-channels')||'null')||[{name:'Little Green Things',about:'Plant people, sharing what’s growing 🌱',members:128,emoji:'🌿'},{name:'Weekend Frames',about:'A cozy corner for photo walks and film.',members:84,emoji:'📷'}],activeChannel:0,feedFilter:'For you',exploreFilter:'For you',search:'',reelIndex:0,auth:null,authMode:'login',postType:'text',videoBytes:Number(localStorage.getItem('hnm-video-bytes')||0),liked:{},disliked:{},commentLikes:{},followedPeople:[],profile:JSON.parse(localStorage.getItem('hnm-profile')||'null')||me,users:JSON.parse(localStorage.getItem('hnm-users')||'[]'),signedIn:localStorage.getItem('hnm-user')||''};
const persist=()=>{localStorage.setItem('hnm-posts',JSON.stringify(state.posts));localStorage.setItem('hnm-following',JSON.stringify(state.following));localStorage.setItem('hnm-notifs',JSON.stringify(state.notifications));localStorage.setItem('hnm-messages',JSON.stringify(state.messages));localStorage.setItem('hnm-channels',JSON.stringify(state.channels));localStorage.setItem('hnm-video-bytes',state.videoBytes);localStorage.setItem('hnm-profile',JSON.stringify(state.profile));localStorage.setItem('hnm-users',JSON.stringify(state.users));};
document.documentElement.dataset.theme=state.theme;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(msg){const root=document.getElementById('toastRoot');root.innerHTML=`<div class="toast">${esc(msg)}</div>`;setTimeout(()=>root.innerHTML='',3000)}
function avatar(url,cls='avatar'){return `<img class="${cls}" src="${url}" alt="">`}
function addNotification(type,person,text){state.notifications.unshift({type,person,text,time:'just now',read:false});persist()}
function setPage(page){state.page=page;if(page==='create')state.postType='text';render()}
function navActive(){document.querySelectorAll('[data-page]').forEach(x=>x.classList.toggle('active',x.dataset.page===state.page));}
function render(){document.documentElement.dataset.theme=state.theme;const title={home:'Home',explore:'Explore',reels:'Reels',create:'Create post',notifications:'Notifications',messages:'Messages',channels:'Channels',profile:'Your profile'}[state.page]||'Home';document.getElementById('pageTitle').textContent=title;navActive();const page=document.getElementById('pageContent');const rail=document.getElementById('rightRail');const views={home:renderHome,explore:renderExplore,reels:renderReels,create:renderCreate,notifications:renderNotifications,messages:renderMessages,channels:renderChannels,profile:renderProfile};page.innerHTML=(views[state.page]||renderHome)();rail.innerHTML=state.page==='home'?renderRail():'';bindPage();}
function renderRail(){return `<div class="rail-card"><h3>People to know <button class="text-link" style="float:right" data-action="morePeople">See all</button></h3>${people.filter(p=>!state.following.includes(p.handle)).slice(0,3).map(p=>`<div class="user-row">${avatar(p.pic)}<span class="user-info"><strong>${esc(p.name)}</strong><small>@${esc(p.handle)}</small></span><button class="follow-button" data-action="follow" data-handle="${p.handle}">Follow</button></div>`).join('')}</div><div class="rail-card"><h3>Your space, your pace 🌱</h3><div style="font-size:11px;color:var(--muted);line-height:1.6">A little more connection, a little less noise. Follow the people who make your day brighter.</div></div><div class="rail-footer">About · Community · Privacy · Guidelines<br>© 2025 Hnmgram <span class="sample-badge">PREVIEW CONTENT</span></div>`}
function renderStories(){return `<div class="stories"><button class="story add" data-action="addStory"><span class="story-ring">＋</span><span>Your story</span></button>${people.map((p,i)=>`<button class="story" data-action="story" data-index="${i}"><span class="story-ring ${i===4?'seen':''}">${avatar(p.pic,'')}</span><span>${esc(p.name.split(' ')[0])}</span></button>`).join('')}</div>`}
function renderHome(){return `<div class="section-heading"><div><h2>Your little corner of the world</h2><p>Good things are happening around you.</p></div><button class="text-link" data-action="feedFilter">${esc(state.feedFilter)}⌄</button></div>${renderStories()}<div class="feed-compose">${avatar(state.profile.pic)}<button class="compose-prompt" data-action="create">What’s on your mind, ${esc(state.profile.name.split(' ')[0])}?</button><div class="compose-tools"><button data-action="createPhoto" title="Add a photo">▧</button><button data-action="createVideo" title="Add a video">▷</button></div></div>${state.posts.map(renderPost).join('')}`}
function renderPost(post){const author=post.author||state.profile;const liked=state.liked[post.id],disliked=state.disliked[post.id];let media='';if(post.video){media=`<video class="post-media" controls playsinline loop src="${esc(post.video)}"></video>`}else if(post.image){media=`<img class="post-media" src="${esc(post.image)}" alt="Post from ${esc(author.name)}">`};return `<article class="post-card" data-post="${post.id}"><div class="post-head">${avatar(author.pic)}<div class="post-author"><strong>${esc(author.name)} ${post.sample?'<span class="sample-badge">SAMPLE</span>':''}</strong><span>@${esc(author.handle)} · ${esc(post.time||'now')}</span></div><button class="post-menu" data-action="postMenu" data-id="${post.id}" aria-label="Post options">•••</button></div>${post.text?`<p class="post-copy">${esc(post.text)}</p>`:''}${media}<div class="post-actions"><button class="action-button ${liked?'selected':''}" data-action="like" data-id="${post.id}" aria-label="Like">♡ <span>${post.likes+(liked?1:0)}</span></button><button class="action-button disliked ${disliked?'selected':''}" data-action="dislike" data-id="${post.id}" aria-label="Dislike">☟</button><button class="action-button" data-action="comments" data-id="${post.id}" aria-label="Comments">▢ <span>${post.comments?.length||0}</span></button><button class="action-button" data-action="share" data-id="${post.id}" aria-label="Share">↗</button><button class="action-button" data-action="reshare" data-id="${post.id}" aria-label="Reshare">⟳</button></div><div class="post-likes">Liked by <b>${post.likes+(liked?1:0)} people</b> · <button class="text-link" style="padding:0" data-action="comments" data-id="${post.id}">View all ${post.comments?.length||0} comments</button></div></article>`}
function renderExplore(){const all=[...state.posts,...state.posts.slice(0,3)];const filtered=all.filter(p=>!state.search||`${p.text} ${p.author?.name}`.toLowerCase().includes(state.search.toLowerCase()));return `<div class="page-banner"><div><h1>Find your next favorite</h1><p>Fresh ideas, kind people, good things.</p></div></div><label class="search-box"><span>⌕</span><input id="exploreSearch" placeholder="Search people, places, things..." value="${esc(state.search)}"></label><div class="tag-row">${['For you','People','Places','Photography','Food','Outdoors','Design'].map(x=>`<button class="tag-chip ${state.exploreFilter===x?'active':''}" data-action="exploreFilter" data-value="${x}">${x}</button>`).join('')}</div><div class="section-heading"><h2>${state.exploreFilter==='People'?'People you might love':'A little inspiration'}</h2><span class="sample-badge">SAMPLE PREVIEW</span></div>${state.exploreFilter==='People'?`<div class="rail-card">${people.map(p=>`<div class="user-row">${avatar(p.pic)}<span class="user-info"><strong>${esc(p.name)}</strong><small>@${esc(p.handle)} · ${p.place}</small></span><button class="follow-button" data-action="follow" data-handle="${p.handle}">${state.following.includes(p.handle)?'Following':'Follow'}</button></div>`).join('')}</div>`:`<div class="explore-grid">${filtered.map((p,i)=>`<button class="explore-tile" data-action="openPost" data-id="${p.id}"><img src="${p.image||people[i%people.length].pic}" alt="Explore post"><span class="tile-overlay">♡ ${p.likes} · ${esc(p.author?.name||'You')}</span></button>`).join('')}</div>`}`}
const reels=[{user:people[4],image:img('photo-1470252649378-9c29740c9fa8',800,1200),caption:'A little golden hour magic ✨ #slowdays'},{user:people[2],image:img('photo-1500530855697-b586d89ba3ee',800,1200),caption:'Took the long way home. Always take the long way. 🌿'},{user:people[0],image:img('photo-1518837695005-2083093ee35b',800,1200),caption:'Ocean air and no plans. My kind of weekend 🌊'}];
function renderReels(){const r=reels[state.reelIndex%reels.length];return `<div class="page-banner"><div><h1>Reels</h1><p>Little moments, on repeat.</p></div><span class="account-pill">Swipe to explore ↑↓</span></div><div class="reel-stage" id="reelStage" data-index="${state.reelIndex}"><img src="${r.image}" alt="Vertical reel by ${r.user.name}"><div class="reel-shade"></div><button class="reel-play" data-action="playReel" aria-label="Play reel">▶</button><span class="video-label">PREVIEW CLIP</span><div class="reel-meta"><strong>@${r.user.handle}</strong><p>${r.caption}</p><button class="button-primary" data-action="follow" data-handle="${r.user.handle}">＋ Follow</button></div><div class="reel-actions"><button data-action="reelLike">♡</button><button data-action="comments" data-id="p1">▢</button><button data-action="share">↗</button></div></div><p class="reel-hint">Tap to play · swipe or use ↑ ↓ to see another</p>`}

function renderCreate(){return `<div class="page-banner"><div><h1>Create a post</h1><p>Share a moment with your people.</p></div></div><form class="form-card" id="postForm"><h2>Your story, your way</h2><p>Text, photos, and videos are all welcome here.</p><div class="tag-row">${['text','photo','video'].map(t=>`<button type="button" class="tag-chip ${state.postType===t?'active':''}" data-action="postType" data-value="${t}">${t==='text'?'✎ Text':t==='photo'?'▧ Photo':'▷ Video'}</button>`).join('')}</div><label class="form-label" for="postText">Say something</label><textarea class="text-area" id="postText" placeholder="What would you like to share?" maxlength="700"></textarea>${state.postType==='photo'?`<label class="upload-zone">Choose a photo<input id="postFile" type="file" accept="image/*"><span id="fileHint">JPG, PNG, GIF or WebP</span></label>`:''}${state.postType==='video'?`<label class="upload-zone">Choose a video<input id="postFile" type="file" accept="video/*"><span id="fileHint">Maximum 10 MB per video · ${fmtBytes(state.videoBytes)} used of 100 MB total</span></label><div class="upload-progress"><div class="progress-label"><span>Hnmgram video storage</span><b>${fmtBytes(state.videoBytes)} used · ${fmtBytes(Math.max(0,104857600-state.videoBytes))} remaining</b></div><div class="progress-track"><span style="width:${Math.min(100,state.videoBytes/1048576)}%"></span></div></div><p class="helper-note">Videos over 10 MB or beyond the 100 MB total storage limit cannot be added. If a file is too large, choose a smaller clip.</p>`:''}<div id="previewWrap"></div><button class="button-primary" style="width:100%;margin-top:8px;padding:12px" type="submit">Share with your people ↗</button></form>`}
function fmtBytes(n){if(n<1024)return `${n} B`;return `${(n/1048576).toFixed(1)} MB`}
function renderNotifications(){const base=[{person:people[0],text:'started following you',type:'follow',time:'12 min'},{person:people[2],text:'liked your photo',type:'like',time:'1 hr'},{person:people[3],text:'commented: “The colors are everything!”',type:'comment',time:'3 hr'}];const items=[...state.notifications,...base];return `<div class="page-banner"><div><h1>Notifications</h1><p>All the little ways people show they care.</p></div><button class="text-link" data-action="markRead">Mark all read</button></div><div class="notifications-list">${items.map(n=>`<div class="notification-row">${avatar(n.person?.pic||people[0].pic)}<div class="notification-copy"><b>${esc(n.person?.name||'Hnmgram member')}</b> ${esc(n.text)}${n.type==='follow'?` <button class="text-link" style="padding:0" data-action="follow" data-handle="${n.person?.handle}">Follow back</button>`:''}<small>${esc(n.time)} · ${n.read?'Seen':'New'}</small></div>${n.type==='like'?`<span style="font-size:20px">💚</span>`:''}</div>`).join('')}</div>`}
function renderMessages(){const tabs=[['general','🌍 General chat'],...people.slice(0,4).map(p=>[p.handle,`◯ ${p.name}`]),...state.channels.map((c,i)=>[`channel-${i}`,`${c.emoji} ${c.name}`])];const selected=state.messageTab;const selectedPerson=people.find(p=>p.handle===selected);const channelIndex=selected.startsWith('channel-')?Number(selected.split('-')[1]):-1;const title=selected==='general'?'Everyone · General chat':selectedPerson?.name||state.channels[channelIndex]?.name||'Chat';const messages=state.messages[selected]||[];return `<div class="page-banner"><div><h1>Messages</h1><p>Say hello. Stay a little longer.</p></div><button class="button-secondary" data-action="newMessage">＋ New</button></div><div class="chat-layout"><div class="chat-list">${tabs.map(([id,label])=>`<button class="chat-tab ${selected===id?'active':''}" data-action="chatTab" data-value="${id}">${label}</button>`).join('')}</div><div class="chat-room"><div class="chat-room-head">${esc(title)}<small>${selected==='general'?'A shared space for everyone on Hnmgram':selected.startsWith('channel-')?'Channel chat · be kind, keep it cozy':'Private conversation'}</small></div><div class="chat-messages" id="chatMessages">${messages.map(m=>`<div class="chat-message ${m.mine?'mine':''}"><small>${esc(m.by)} · ${esc(m.time)}</small><span class="chat-bubble">${esc(m.text)}</span></div>`).join('')||'<div class="empty-state">No messages yet.<b>Be the first to say hello!</b></div>'}</div><form class="chat-compose" id="chatForm"><input id="chatInput" placeholder="Write a message..." autocomplete="off" required><button class="button-primary">Send</button></form></div></div>`}
function renderChannels(){return `<div class="page-banner"><div><h1>Channels</h1><p>Find your people around the things you love.</p></div><button class="button-primary" data-action="newChannel">＋ Create channel</button></div><div class="rail-card" style="margin-bottom:17px"><h3>🌍 General chat for everyone</h3><div style="font-size:11px;color:var(--muted);line-height:1.55">Drop in, say hi, and meet the Hnmgram community.</div><button class="button-secondary" style="margin-top:12px" data-action="openGeneral">Open general chat →</button></div><div class="section-heading"><h2>Community channels</h2><span class="sample-badge">${state.channels.length} CHANNELS</span></div>${state.channels.map((c,i)=>`<article class="channel-card"><div style="display:flex;gap:12px;align-items:center"><div style="width:43px;height:43px;border-radius:13px;background:var(--soft-green);display:grid;place-items:center;font-size:21px">${c.emoji}</div><div><h3>${esc(c.name)}</h3><p style="margin:4px 0 0">${esc(c.about)}</p></div></div><div class="channel-card-foot"><span>${c.members} members · Chat + videos</span><button class="button-secondary" data-action="channelOpen" data-index="${i}">Open channel →</button></div></article>`).join('')}`}
function renderProfile(){const p=state.profile;const posts=state.posts.filter(x=>x.author?.handle===p.handle||x.mine);const shown=state.profileTab==='videos'?posts.filter(x=>x.video):posts;return `<div class="profile-cover"><img class="profile-avatar-large" src="${p.pic}" alt="Profile photo"><button class="button-primary profile-edit" data-action="editProfile">Edit profile</button></div><div class="profile-name-line"><h1>${esc(p.name)}</h1><span class="account-pill">${state.signedIn?'YOUR ACCOUNT':'LOCAL PREVIEW'}</span></div><div class="profile-handle">@${esc(p.handle)} · ${esc(p.place||'')}</div><p class="profile-bio">${esc(p.bio)}</p><div class="profile-stats"><span><b>${posts.length}</b><small>Posts</small></span><span><b>${state.followersCount||128}</b><small>Followers</small></span><span><b>${state.following.length+3}</b><small>Following</small></span></div><div class="profile-tabs"><button class="${state.profileTab==='posts'?'active':''}" data-action="profileTab" data-value="posts">▦ Posts</button><button class="${state.profileTab==='videos'?'active':''}" data-action="profileTab" data-value="videos">▷ Videos</button><button class="${state.profileTab==='saved'?'active':''}" data-action="profileTab" data-value="saved">♡ Saved</button></div>${shown.length?shown.map(renderPost).join(''):`<div class="empty-state">${state.profileTab==='saved'?'No saved posts yet.':'Your posts will feel right at home here.'}<b>Share a little moment to get started.</b><button class="button-primary" data-action="create">Create a post</button></div>`}`}
function bindPage(){document.querySelectorAll('[data-page]').forEach(el=>el.onclick=()=>setPage(el.dataset.page));document.getElementById('themeToggle').onclick=toggleTheme;document.getElementById('topTheme').onclick=toggleTheme;document.querySelectorAll('[data-action]').forEach(el=>el.onclick=e=>{if(el.tagName==='BUTTON'&&el.closest('form')&&el.type==='submit')return;handleAction(el.dataset.action,el.dataset,e)});const search=document.getElementById('exploreSearch');if(search)search.oninput=()=>{state.search=search.value;const cursor=search.selectionStart;render();const next=document.getElementById('exploreSearch');next.focus();next.setSelectionRange(cursor,cursor)};const form=document.getElementById('postForm');if(form)form.onsubmit=submitPost;const chat=document.getElementById('chatForm');if(chat)chat.onsubmit=sendMessage;const file=document.getElementById('postFile');if(file)file.onchange=previewFile;const stage=document.getElementById('reelStage');if(stage){let sy=0;stage.ontouchstart=e=>sy=e.touches[0].clientY;stage.ontouchend=e=>{const dy=sy-e.changedTouches[0].clientY;if(Math.abs(dy)>40){state.reelIndex=(state.reelIndex+(dy>0?1:reels.length-1))%reels.length;render()}};stage.onclick=e=>{if(e.target===stage||e.target.tagName==='IMG')toggleReelPlay()}}}
function toggleTheme(){state.theme=state.theme==='light'?'dark':'light';localStorage.setItem('hnm-theme',state.theme);render()}
function handleAction(action,data,e){switch(action){case'like':state.liked[data.id]=!state.liked[data.id];if(state.liked[data.id])addNotification('like',state.profile,'liked your post');render();break;case'dislike':state.disliked[data.id]=!state.disliked[data.id];state.liked[data.id]=false;render();break;case'comments':openComments(data.id);break;case'share':sharePost(data.id);break;case'reshare':toast('Added to your profile');break;case'follow':toggleFollow(data.handle);break;case'create':setPage('create');break;case'createPhoto':state.postType='photo';setPage('create');break;case'createVideo':state.postType='video';setPage('create');break;case'postType':state.postType=data.value;render();break;case'feedFilter':openFeedFilters();break;case'exploreFilter':state.exploreFilter=data.value;render();break;case'profileTab':state.profileTab=data.value;render();break;case'editProfile':openProfileEditor();break;case'chatTab':state.messageTab=data.value;render();break;case'newMessage':openNewMessage();break;case'newChannel':openChannelForm();break;case'channelOpen':state.messageTab=`channel-${data.index}`;setPage('messages');break;case'openGeneral':state.messageTab='general';setPage('messages');break;case'markRead':state.notifications=state.notifications.map(n=>({...n,read:true}));persist();render();toast('You’re all caught up');break;case'addStory':toast('Choose a photo in Create post to share a moment');break;case'story':openStory(Number(data.index));break;case'openPost':const p=state.posts.find(x=>x.id===data.id);if(p)openComments(p.id);break;case'postMenu':openPostOptions(data.id);break;case'morePeople':state.exploreFilter='People';setPage('explore');break;case'playReel':toggleReelPlay();break;case'reelLike':toast('You liked this reel 💚');break;}}
function toggleFollow(handle){if(!handle)return;const i=state.following.indexOf(handle);if(i<0){state.following.push(handle);addNotification('follow',{...people.find(p=>p.handle===handle)||{name:handle,pic:state.profile.pic,handle}},'started following you');toast('You’re following @'+handle)}else{state.following.splice(i,1);toast('Unfollowed @'+handle)}persist();render()}
function submitPost(e){e.preventDefault();const text=document.getElementById('postText').value.trim();const file=document.getElementById('postFile')?.files?.[0];if(!text&&!file){toast('Add a caption or choose a photo/video first');return}if(file&&state.postType==='video'){if(file.size>10*1048576){toast('That video is over the 10 MB per-video limit. Choose a smaller clip.');return}if(state.videoBytes+file.size>100*1048576){toast(`Storage limit reached. ${fmtBytes(Math.max(0,100*1048576-state.videoBytes))} remaining.`);return}state.videoBytes+=file.size;localStorage.setItem('hnm-video-bytes',state.videoBytes)}const post={id:'u'+Date.now(),author:state.profile,text,likes:0,comments:[],time:'now',mine:true};if(file){post.image=state.postType==='photo'?URL.createObjectURL(file):null;post.video=state.postType==='video'?URL.createObjectURL(file):null;post.bytes=state.postType==='video'?file.size:0}state.posts.unshift(post);persist();state.page='home';render();toast('Your post is out in the world ✨')}
function previewFile(e){const f=e.target.files[0];if(!f)return;const hint=document.getElementById('fileHint');if(state.postType==='video'){if(f.size>10485760){hint.textContent='⚠ This video is over 10 MB. Please choose a smaller file.';hint.style.color='#db5266';return}if(state.videoBytes+f.size>104857600){hint.textContent=`⚠ Storage limit reached. ${fmtBytes(104857600-state.videoBytes)} remaining.`;hint.style.color='#db5266';return}hint.textContent=`${f.name} · ${fmtBytes(f.size)} · ${fmtBytes(104857600-state.videoBytes-f.size)} remaining`}else hint.textContent=`${f.name} · ${fmtBytes(f.size)}`;document.getElementById('previewWrap').innerHTML=state.postType==='photo'?`<img style="width:100%;border-radius:12px;max-height:300px;object-fit:cover" src="${URL.createObjectURL(f)}" alt="Preview">`:''}
function sendMessage(e){e.preventDefault();const input=document.getElementById('chatInput'),text=input.value.trim();if(!text)return;const key=state.messageTab;state.messages[key]??=[];state.messages[key].push({by:state.profile.name,text,time:new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}),mine:true});if(key==='general')addNotification('message',people[1],'sent a message in General chat');persist();render();document.getElementById('chatMessages').scrollTop=99999}
function sharePost(id){const post=state.posts.find(p=>p.id===id);const url=location.href.split('#')[0]+'#post-'+id;if(navigator.share)navigator.share({title:'Hnmgram',text:post?.text||'A moment from Hnmgram',url}).catch(()=>{});else if(navigator.clipboard)navigator.clipboard.writeText(url).then(()=>toast('Post link copied')).catch(()=>toast('Ready to share'));else toast('Post link: '+url)}
function toggleReelPlay(){const b=document.querySelector('.reel-play');if(!b)return;const paused=b.dataset.paused==='true';b.dataset.paused=paused?'false':'true';b.textContent=paused?'▶':'Ⅱ';toast(paused?'Reel playing · tap to pause':'Reel paused')}
window.addEventListener('keydown',e=>{if(state.page==='reels'&&(e.key==='ArrowDown'||e.key==='ArrowUp')){state.reelIndex=(state.reelIndex+(e.key==='ArrowDown'?1:reels.length-1))%reels.length;render()}});

function showModal(html,cls=''){const root=document.getElementById('modalRoot');root.innerHTML=`<div class="modal-backdrop" data-dismiss="true"><section class="modal ${cls}" role="dialog" aria-modal="true">${html}</section></div>`;root.querySelector('.modal-backdrop').onclick=e=>{if(e.target.dataset.dismiss)root.innerHTML=''};root.querySelectorAll('[data-modal-close]').forEach(b=>b.onclick=()=>root.innerHTML='')}
function openComments(id){const post=state.posts.find(p=>p.id===id);if(!post)return;state.commentsPost=id;const comments=post.comments||[];showModal(`<div class="modal-top"><h2>Comments <span style="color:var(--muted);font-weight:500">${comments.length}</span></h2><button class="modal-close" data-modal-close>×</button></div><div class="comment-list">${comments.length?comments.map((c,i)=>`<div class="comment-row">${avatar(c.by?.pic||people[(i+2)%people.length].pic,'')}<div class="comment-body"><b>${esc(c.by?.name||'Hnmgram friend')}</b>${esc(c.text)}<small>${c.time||'a little while ago'} · ${c.likes||0} likes · <button class="text-link" style="padding:0" data-reply="${i}">Reply</button></small></div><button class="comment-like" data-clike="${i}">♡</button></div>`).join(''):'<div class="empty-state">It’s nice and quiet here.<b>Start a kind conversation ✨</b></div>'}</div><form class="comment-compose" id="commentForm">${avatar(state.profile.pic)}<input id="commentInput" placeholder="Add a kind comment..." required maxlength="300"><button class="button-primary">Post</button></form>`,'comments');document.getElementById('commentForm').onsubmit=e=>{e.preventDefault();const text=document.getElementById('commentInput').value.trim();if(!text)return;post.comments??=[];post.comments.push({by:state.profile,text,likes:0,time:'just now'});addNotification('comment',post.author,'commented on your post');persist();render();openComments(id)};document.querySelectorAll('[data-clike]').forEach(b=>b.onclick=()=>{const c=post.comments[b.dataset.clike];c.likes=(c.likes||0)+1;persist();openComments(id)});document.querySelectorAll('[data-reply]').forEach(b=>b.onclick=()=>{const c=post.comments[b.dataset.reply];document.getElementById('commentInput').value=`@${c.by?.handle||'friend'} `;document.getElementById('commentInput').focus()})}
function openProfileEditor(){const p=state.profile;showModal(`<div class="modal-top"><h2>Edit your profile</h2><button class="modal-close" data-modal-close>×</button></div><form id="profileForm"><label class="form-label">Profile photo URL</label><input class="text-input" name="pic" value="${esc(p.pic)}" placeholder="https://..."><p class="helper-note">Use a photo URL for this local preview.</p><label class="form-label">Display name</label><input class="text-input" name="name" value="${esc(p.name)}" required maxlength="45"><label class="form-label">Username</label><input class="text-input" name="handle" value="${esc(p.handle)}" required pattern="[A-Za-z0-9_.]{3,24}"><label class="form-label">Bio</label><textarea class="text-area" name="bio" maxlength="160">${esc(p.bio)}</textarea><button class="button-primary" style="width:100%;margin-top:17px">Save changes</button></form>`);document.getElementById('profileForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);state.profile={...state.profile,name:f.get('name').trim(),handle:f.get('handle').trim().replace(/^@/,''),pic:f.get('pic').trim()||p.pic,bio:f.get('bio').trim()};persist();document.querySelector('.top-avatar img').src=state.profile.pic;document.querySelector('.profile-shortcut img').src=state.profile.pic;document.querySelector('.profile-shortcut b').textContent=state.profile.name;document.querySelector('.profile-shortcut small').textContent='@'+state.profile.handle;document.getElementById('modalRoot').innerHTML='';render();toast('Profile updated')};}
function openFeedFilters(){showModal(`<div class="modal-top"><h2>Your Home feed</h2><button class="modal-close" data-modal-close>×</button></div><p class="helper-note">Choose what you’d like to see first.</p>${['For you','Following'].map(x=>`<button class="chat-tab ${state.feedFilter===x?'active':''}" style="padding:13px;width:100%" data-feed="${x}">${x==='For you'?'✦':'◉'} ${x}</button>`).join('')}`);document.querySelectorAll('[data-feed]').forEach(b=>b.onclick=()=>{state.feedFilter=b.dataset.feed;document.getElementById('modalRoot').innerHTML='';render()})}
function openNewMessage(){showModal(`<div class="modal-top"><h2>Start a conversation</h2><button class="modal-close" data-modal-close>×</button></div><p class="helper-note">Choose someone to send a private message.</p>${people.map(p=>`<button class="user-row" style="width:100%;border:0;background:none;text-align:left" data-newchat="${p.handle}">${avatar(p.pic)}<span class="user-info"><strong>${esc(p.name)}</strong><small>@${esc(p.handle)}</small></span><span>›</span></button>`).join('')}`);document.querySelectorAll('[data-newchat]').forEach(b=>b.onclick=()=>{state.messageTab=b.dataset.newchat;state.messages[state.messageTab]??=[];document.getElementById('modalRoot').innerHTML='';render()})}
function openChannelForm(){showModal(`<div class="modal-top"><h2>Create a channel</h2><button class="modal-close" data-modal-close>×</button></div><p class="helper-note">Start a shared space. Every channel includes chat and a video section.</p><form id="channelForm"><label class="form-label">Channel name</label><input class="text-input" name="name" placeholder="e.g. Morning Gardeners" maxlength="36" required><label class="form-label">What’s it about?</label><textarea class="text-area" name="about" placeholder="Tell people what you love to share..." maxlength="120" required></textarea><label class="form-label">Pick an emoji</label><select class="text-input" name="emoji"><option>🌿</option><option>🎨</option><option>📷</option><option>🍜</option><option>🎧</option><option>🏕️</option></select><button class="button-primary" style="width:100%;margin-top:17px">Create channel</button></form>`);document.getElementById('channelForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);state.channels.push({name:f.get('name').trim(),about:f.get('about').trim(),emoji:f.get('emoji'),members:1,owner:state.profile.handle});persist();document.getElementById('modalRoot').innerHTML='';render();toast('Your channel is ready ✨')}}
function openStory(index){const p=people[index%people.length];showModal(`<div class="modal-top"><h2>${esc(p.name)}’s moment</h2><button class="modal-close" data-modal-close>×</button></div><div class="story-view"><div class="story-progress"><span></span></div><img src="${img(['photo-1470252649378-9c29740c9fa8','photo-1500530855697-b586d89ba3ee','photo-1518837695005-2083093ee35b'][index%3],800,1000)}" alt="Sample story"><div style="position:absolute;bottom:15px;left:15px;font-weight:700">${esc(p.name)} <span class="sample-badge">SAMPLE STORY</span></div></div>`)}
function openPostOptions(id){const post=state.posts.find(p=>p.id===id);showModal(`<div class="modal-top"><h2>Post options</h2><button class="modal-close" data-modal-close>×</button></div><button class="chat-tab" data-opt="save">♡ Save post</button><button class="chat-tab" data-opt="share">↗ Share post</button><button class="chat-tab" data-opt="report">⚑ Report post</button>${post?.mine?'<button class="chat-tab" data-opt="delete" style="color:#dc5368">⌫ Delete post</button>':''}`);document.querySelectorAll('[data-opt]').forEach(b=>b.onclick=()=>{const action=b.dataset.opt;document.getElementById('modalRoot').innerHTML='';if(action==='delete'&&post?.mine){state.posts=state.posts.filter(x=>x.id!==id);persist();render();toast('Post deleted')}else if(action==='share')sharePost(id);else toast(action==='save'?'Post saved':'Thanks for looking out for the community')})}
function openAuth(mode='login'){state.authMode=mode;const recovering=mode==='recovery';const signup=mode==='signup';const root=document.createElement('div');root.className='auth-screen';root.id='authScreen';root.innerHTML=`<div class="auth-box ${recovering?'recovery':''}"><section class="auth-art"><div class="auth-logo"><span class="brand-mark"><svg viewBox="0 0 32 32"><path d="M12 8.5v15l12-7.5z"/></svg></span>Hnmgram</div><div><h1>${recovering?'A fresh start, just a link away.':signup?'Find your people.':'A little more connection.'}</h1><p>${recovering?'We’ll send a reset link to your inbox.':signup?'Your kind of community is waiting.':'A little less noise. A lot more you.'}</p><p class="auth-tagline">alternatifimiz aynı ama amaçlar farklı</p></div><small>A friendly place to find your people.</small></section><section class="auth-form"><h2>${recovering?'Reset your password':signup?'Create your account':'Welcome back'}</h2><p>${recovering?'Enter the email address you signed up with.':signup?'No invite needed. Everyone is welcome.':'Your corner of the world is right here.'}</p><form id="authForm">${!recovering&&signup?`<label class="form-label">Display name</label><input class="text-input" name="name" placeholder="Your name" required maxlength="45">`:''}<label class="form-label">Email address</label><input class="text-input" type="email" name="email" placeholder="you@example.com" required autocomplete="email">${!recovering?`<label class="form-label">Password</label><input class="text-input" type="password" name="password" placeholder="At least 8 characters" required minlength="8" autocomplete="${signup?'new-password':'current-password'}">${!signup?`<div style="text-align:right;margin-top:8px"><button type="button" class="auth-link" id="forgotBtn">Forgot password?</button></div>`:''}`:''}<button class="button-primary auth-submit" type="submit">${recovering?'Send reset email':signup?'Create account':'Log in'}</button></form>${!recovering?`<div class="auth-divider">or continue with</div><div class="social-buttons"><button class="social-button" data-social="google">🌐 Continue with Google</button><button class="social-button" data-social="apple"> Continue with Apple</button></div>`:''}<p class="auth-switch">${recovering?'Remember your password?':signup?'Already have an account?':'New to Hnmgram?'} <button id="authSwitch">${recovering?'Log in':signup?'Log in':'Create account'}</button></p><p class="helper-note" style="text-align:center;margin-top:8px">Local preview · account data stays in this browser</p></section></div>`;document.body.appendChild(root);root.querySelector('#authSwitch').onclick=()=>{root.remove();openAuth(recovering?'login':signup?'login':'signup')};if(root.querySelector('#forgotBtn'))root.querySelector('#forgotBtn').onclick=()=>{root.remove();openAuth('recovery')};root.querySelector('#authForm').onsubmit=e=>{e.preventDefault();handleAuth(new FormData(e.target),mode)};root.querySelectorAll('[data-social]').forEach(b=>b.onclick=()=>socialAuthNotice(b.dataset.social));}
function handleAuth(form,mode){const email=String(form.get('email')).trim().toLowerCase(),password=String(form.get('password')||'');if(mode==='recovery'){const exists=state.users.some(u=>u.email===email);document.getElementById('authScreen')?.remove();toast(exists?'In this local preview, reset links can’t be emailed. Use the same browser to continue.':'If an account exists, a reset link would be sent.');return}if(mode==='signup'){if(state.users.some(u=>u.email===email)){toast('An account already exists for that email in this browser. Log in instead.');return}const user={id:crypto.randomUUID?.()||String(Date.now()),email,password,name:form.get('name').trim(),handle:email.split('@')[0].replace(/[^a-z0-9_.]/g,'').slice(0,20)||'newfriend'};state.users.push(user);state.signedIn=user.id;state.profile={...me,name:user.name,handle:user.handle};localStorage.setItem('hnm-user',user.id);persist();document.getElementById('authScreen')?.remove();render();toast(`Welcome to Hnmgram, ${user.name.split(' ')[0]}!`);return}const user=state.users.find(u=>u.email===email&&u.password===password);if(!user){toast('We couldn’t find that email and password in this browser.');return}state.signedIn=user.id;state.profile={...state.profile,name:user.name,handle:user.handle};localStorage.setItem('hnm-user',user.id);persist();document.getElementById('authScreen')?.remove();render();toast('Welcome back!')}
function socialAuthNotice(provider){toast(`${provider==='google'?'Google':'Apple'} sign-in needs verified app credentials. No fake sign-in is enabled in this preview.`)}

