5: function openFeedFilters(){showModal(`<div class="modal-top"><h2>Your Home feed</h2><button class="modal-close" data-modal-close>×</button></div><p class="helper-note">Choose what you’d like to see first.</p>${['For you','Following'].map(x=>`<button class="chat-tab ${state.feedFilter===x?'active':''}" style="padding:13px;width:100%" data-feed="${x}">${x==='For you'?'✦':'◉'} ${x}</button>`).join('')}`);document.querySelectorAll('[data-feed]').forEach(b=>b.onclick=()=>{state.feedFilter=b.dataset.feed;document.getElementById('modalRoot').innerHTML='';render()})}
