7: function openChannelForm(){showModal(`<div class="modal-top"><h2>Create a channel</h2><button class="modal-close" data-modal-close>×</button></div><p class="helper-note">Start a shared space. Every channel includes chat and a video section.</p><form id="channelForm"><label class="form-label">Channel name</label><input class="text-input" name="name" placeholder="e.g. Morning Gardeners" maxlength="36" required><label class="form-label">What’s it about?</label><textarea class="text-area" name="about" placeholder="Tell people what you love to share..." maxlength="120" required></textarea><label class="form-label">Pick an emoji</label><select class="text-input" name="emoji"><option>🌿</option><option>🎨</option><option>📷</option><option>🍜</option><option>🎧</option><option>🏕️</option></select><button class="button-primary" style="width:100%;margin-top:17px">Create channel</button></form>`);document.getElementById('channelForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);state.channels.push({name:f.get('name').trim(),about:f.get('about').trim(),emoji:f.get('emoji'),members:1,owner:state.profile.handle});persist();document.getElementById('modalRoot').innerHTML='';render();toast('Your channel is ready ✨')}}
8: function openStory(index){const p=people[index%people.length];showModal(`<div class="modal-top"><h2>${esc(p.name)}’s moment</h2><button class="modal-close" data-modal-close>×</button></div><div class="story-view"><div class="story-progress"><span></span></div><img src="${img(['photo-1470252649378-9c29740c9fa8','photo-1500530855697-b586d89ba3ee','photo-1518837695005-2083093ee35b'][index%3],800,1000)}" alt="Sample story"><div style="position:absolute;bottom:15px;left:15px;font-weight:700">${esc(p.name)} <span class="sample-badge">SAMPLE STORY</span></div></div>`)}
9: function openPostOptions(id){const post=state.posts.find(p=>p.id===id);showModal(`<div class="modal-top"><h2>Post options</h2><button class="modal-close" data-modal-close>×</button></div><button class="chat-tab" data-opt="save">♡ Save post</button><button class="chat-tab" data-opt="share">↗ Share post</button><button class="chat-tab" data-opt="report">⚑ Report post</button>${post?.mine?'<button class="chat-tab" data-opt="delete" style="color:#dc5368">⌫ Delete post</button>':''}`);document.querySelectorAll('[data-opt]').forEach(b=>b.onclick=()=>{const action=b.dataset.opt;document.getElementById('modalRoot').innerHTML='';if(action==='delete'&&post?.mine){state.posts=state.posts.filter(x=>x.id!==id);persist();render();toast('Post deleted')}else if(action==='share')sharePost(id);else toast(action==='save'?'Post saved':'Thanks for looking out for the community')})}
10: function openAuth(mode='login'){state.authMode=mode;const recovering=mode==='recovery';const signup=mode==='signup';const root=document.createElement('div');root.className='auth-screen';root.id='authScreen';root.innerHTML=`<div class="auth-box ${recovering?'recovery':''}"><section class="auth-art"><div class="auth-logo"><span class="brand-mark"><svg viewBox="0 0 32 32"><path d="M12 8.5v15l12-7.5z"/></svg></span>Hnmgram</div><div><h1>${recovering?'A fresh start, just a link away.':signup?'Find your people.':'A little more connection.'}</h1><p>${recovering?'We’ll send a reset link to your inbox.':signup?'Your kind of community is waiting.':'A little less noise. A lot more you.'}</p><p class="auth-tagline">alternatifimiz aynı ama amaçlar farklı</p></div><small>A friendly place to find your people.</small></section><section class="auth-form"><h2>${recovering?'Reset your password':signup?'Create your account':'Welcome back'}</h2><p>${recovering?'Enter the email address you signed up with.':signup?'No invite needed. Everyone is welcome.':'Your corner of the world is right here.'}</p><form id="authForm">${!recovering&&signup?`<label class="form-label">Display name</label><input class="text-input" name="name" placeholder="Your name" required maxlength="45">`:''}<label class="form-label">Email address</label><input class="text-input" type="email" name="email" placeholder="you@example.com" required autocomplete="email">${!recovering?`<label class="form-label">Password</label><input class="text-input" type="password" name="password" placeholder="At least 8 characters" required minlength="8" autocomplete="${signup?'new-password':'current-password'}">${!signup?`<div style="text-align:right;margin-top:8px"><button type="button" class="auth-link" id="forgotBtn">Forgot password?</button></div>`:''}`:''}<button class="button-primary auth-submit" type="submit">${recovering?'Send reset email':signup?'Create account':'Log in'}</button></form>${!recovering?`<div class="auth-divider">or ... (line truncated to 2000 chars)
11: function handleAuth(form,mode){const email=String(form.get('email')).trim().toLowerCase(),password=String(form.get('password')||'');if(mode==='recovery'){const exists=state.users.some(u=>u.email===email);document.getElementById('authScreen')?.remove();toast(exists?'In this local preview, reset links can’t be emailed. Use the same browser to continue.':'If an account exists, a reset link would be sent.');return}if(mode==='signup'){if(state.users.some(u=>u.email===email)){toast('An account already exists for that email in this browser. Log in instead.');return}const user={id:crypto.randomUUID?.()||String(Date.now()),email,password,name:form.get('name').trim(),handle:email.split('@')[0].replace(/[^a-z0-9_.]/g,'').slice(0,20)||'newfriend'};state.users.push(user);state.signedIn=user.id;state.profile={...me,name:user.name,handle:user.handle};localStorage.setItem('hnm-user',user.id);persist();document.getElementById('authScreen')?.remove();render();toast(`Welcome to Hnmgram, ${user.name.split(' ')[0]}!`);return}const user=state.users.find(u=>u.email===email&&u.password===password);if(!user){toast('We couldn’t find that email and password in this browser.');return}state.signedIn=user.id;state.profile={...state.profile,name:user.name,handle:user.handle};localStorage.setItem('hnm-user',user.id);persist();document.getElementById('authScreen')?.remove();render();toast('Welcome back!')}
