const img=(id,w=600,h=500)=>`https://images.unsplash.com/${id}?auto=format&fit=crop&w=${w}&h=${h}&q=85`;
const people=[{name:'Maya Chen',handle:'mayainmotion',pic:img('photo-1531123897727-8f129e1688ce',100,100)},{name:'Theo Brooks',handle:'theobrooks',pic:img('photo-1500648767791-00dcc994a43e',100,100)},{name:'Nina Flores',handle:'ninaflores',pic:img('photo-1534528741775-53994a69daeb',100,100)},{name:'Oliver Park',handle:'oliverpark',pic:img('photo-1506794778202-cad84cf45f1d',100,100)},{name:'Amara Okafor',handle:'amara.o',pic:img('photo-1534751516642-a1af1ef26a56',100,100)},{name:'Luca Moretti',handle:'lucamoretti',pic:img('photo-1507003211169-0a1dd7228f2d',100,100)}];
const me={name:'Alex Morgan',handle:'alexmorgan',pic:img('photo-1534528741775-53994a69daeb',100,100),bio:'Collecting little moments 🌿 | design, slow travel & good coffee',place:'Portland, OR'};
const seed=[{id:'p1',author:people[0],text:'A slow morning, a warm pastel de nata, and absolutely nowhere to be. Lisbon, you have my whole heart ☀️',image:img('photo-1470252649378-9c29740c9fa8',1000,760),likes:248,comments:[{by:people[1],text:'Adding this to my someday list ✨',likes:12},{by:people[2],text:'That light is unreal!',likes:4}],time:'18 min',sample:true},{id:'p2',author:people[1],text:'Tiny reminder: you don’t have to have it all figured out to take the next step. 🌱',likes:87,comments:[{by:people[4],text:'Needed to hear this today.',likes:8}],time:'1 hr',sample:true},{id:'p3',author:people[3],text:'The city before it wakes up. Just me, my camera, and the last of the blue hour.',image:img('photo-1519501025264-65ba15a82390',1000,760),likes:512,comments:[{by:people[0],text:'The colors! 😍',likes:16}],time:'3 hr',sample:true},{id:'p4',author:people[4],text:'Sunday table, extra chairs, and enough jollof for everyone. That’s the whole plan. ❤️',image:img('photo-1547592180-85f173990554',1000,760),likes:174,comments:[],time:'5 hr',sample:true}];
const get=(k,d)=>{try{return JSON.parse(localStorage.getItem('hnm-'+k))??d}catch{return d}};
const state={page:'home',theme:localStorage.getItem('hnm-theme')||'light',posts:get('posts',seed),following:get('following',[people[0].handle,people[2].handle]),notifications:get('notifs',[]),commentsPost:null,profileTab:'posts',messageTab:'general',activeChannel:0,channelSection:'chat',messages:get('messages',{general:[{by:'Maya Chen',text:'Good morning, Hnmgram ☀️',time:'9:14'},{by:'Theo Brooks',text:'Anyone have a favorite tiny coffee shop in Lisbon?',time:'9:20'}]}),channels:get('channels',[{name:'Little Green Things',about:'Plant people, sharing what’s growing 🌱',members:128,emoji:'🌿',chat:[]},{name:'Weekend Frames',about:'A cozy corner for photo walks and film.',members:84,emoji:'📷',chat:[]}]),search:'',exploreFilter:'For you',feedFilter:'For you',postType:'text',videoBytes:Number(localStorage.getItem('hnm-video-bytes')||0),liked:get('liked',{}),disliked:get('disliked',{}),profile:get('profile',me),users:get('users',[]),signedIn:localStorage.getItem('hnm-user')||'',mediaUrls:{},reelIndex:0,storyIndex:null};
function persist(){for(const k of ['posts','following','notifications','messages','channels','profile','users','liked','disliked'])localStorage.setItem('hnm-'+k,JSON.stringify(state[k]));localStorage.setItem('hnm-video-bytes',state.videoBytes)}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const fmt=n=>n<1024?`${n} B`:`${(n/1048576).toFixed(1)} MB`;
function toast(m){const r=document.getElementById('toastRoot');r.innerHTML=`<div class="toast">${esc(m)}</div>`;setTimeout(()=>r.innerHTML='',3000)}
function avatar(url,cls='avatar'){return `<img class="${cls}" src="${url}" alt="">`}
function notify(type,person,text){state.notifications.unshift({type,person,text,time:'just now',read:false});persist()}
function setPage(p){state.page=p;if(p==='create')state.postType='text';render()}
function toggleTheme(){state.theme=state.theme==='light'?'dark':'light';localStorage.setItem('hnm-theme',state.theme);render()}
const pageNames={home:'Home',explore:'Explore',reels:'Reels',create:'Create post',notifications:'Notifications',messages:'Messages',channels:'Channels',profile:'Your profile'};
function render(){document.documentElement.dataset.theme=state.theme;const title=document.getElementById('pageTitle');if(title)title.textContent=pageNames[state.page]||'Home';document.querySelectorAll('[data-page]').forEach(x=>x.classList.toggle('active',x.dataset.page===state.page));document.getElementById('pageContent').innerHTML=({home,explore,reels:reelsView,create:createView,notifications:notifs,messages,channels,profile}[state.page]||home)();document.getElementById('rightRail').innerHTML=state.page==='home'?rail():'';syncProfileChrome();bind()}
function syncProfileChrome(){document.querySelectorAll('.profile-shortcut b').forEach(e=>e.textContent=state.profile.name);document.querySelectorAll('.profile-shortcut small').forEach(e=>e.textContent='@'+state.profile.handle);document.querySelectorAll('.profile-shortcut .avatar,.top-avatar img').forEach(e=>e.src=state.profile.pic)}
function rail(){return `<div class="rail-card"><h3>People to know</h3>${people.filter(p=>!state.following.includes(p.handle)).slice(0,3).map(p=>`<div class="user-row">${avatar(p.pic)}<span class="user-info"><strong>${esc(p.name)}</strong><small>@${esc(p.handle)}</small></span><button class="follow-button" data-do="follow" data-h="${p.handle}">Follow</button></div>`).join('')}</div><div class="rail-card"><h3>Your space, your pace 🌱</h3><div style="font-size:11px;color:var(--muted);line-height:1.6">A little more connection, a little less noise. Follow the people who make your day brighter.</div></div><div class="rail-footer">About · Community · Privacy · Guidelines<br>© 2025 Hnmgram <span class="sample-badge">PREVIEW CONTENT</span></div>`}
function stories(){return `<div class="stories"><button class="story add" data-do="addStory"><span class="story-ring">＋</span><span>Your story</span></button>${people.filter(p=>state.following.includes(p.handle)).map((p,i)=>`<button class="story" data-do="story" data-i="${people.indexOf(p)}"><span class="story-ring ${i===1?'seen':''}">${avatar(p.pic,'')}</span><span>${esc(p.name.split(' ')[0])}</span></button>`).join('')}</div>`}
