function notifs(){if(!state.notifications.length)return `<div class="page-banner"><div><h1>Your activity</h1><p>Little moments of connection.</p></div></div><div class="empty-state">You’re all caught up 🌿<br><small>New likes, follows, and replies will show here.</small></div>`;return `<div class="page-banner"><div><h1>Your activity</h1><p>Little moments of connection.</p></div><button class="text-link" data-do="readAll">Mark all read</button></div><div class="rail-card">${state.notifications.map(n=>`<div class="user-row notification-row ${n.read?'read':''}">${avatar(n.person?.pic||people[0].pic)}<span class="user-info"><strong>${esc(n.person?.name||'Hnmgram')}</strong><small>${esc(n.text)} · ${esc(n.time)}</small></span>${n.read?'':'<span class="unread-dot"></span>'}</div>`).join('')}</div>`}
function chatData(){return state.messageTab==='general'?state.messages.general:(state.messages[state.messageTab]||[])}
function messages(){const tabs=[['general','General chat'],...people.map(p=>[p.handle,p.name])],data=chatData();return `<div class="page-banner"><div><h1>Messages</h1><p>Say hello, share a little kindness.</p></div></div><div class="chat-layout"><aside class="chat-list">${tabs.map(([id,n])=>`<button class="chat-tab ${state.messageTab===id?'active':''}" data-do="chatTab" data-val="${id}">${esc(n)}</button>`).join('')}</aside><section class="chat-room"><div class="chat-room-head"><strong>${state.messageTab==='general'?'Hnmgram community':esc(people.find(p=>p.handle===state.messageTab)?.name||state.messageTab)}</strong><small>${state.messageTab==='general'?'Shared preview chat':'Private message preview'}</small></div><div class="chat-messages" id="chatMessages">${data.map(m=>`<div class="chat-bubble ${m.by===state.profile.name?'mine':''}"><small>${esc(m.by)}</small><p>${esc(m.text)}</p><time>${esc(m.time)}</time></div>`).join('')||'<p class="helper-note">Start the conversation with a kind hello.</p>'}</div><form class="chat-compose" id="chatForm"><input id="chatInput" placeholder="Write a message..." maxlength="500" required><button class="button-primary">Send</button></form></section></div><p class="helper-note">Preview messages are stored only in this browser.</p>`}
EOF

