function showModal(html){const root=document.getElementById('modalRoot');root.innerHTML=`<div class="modal-backdrop" data-do="closeModal"><div class="modal" role="dialog" aria-modal="true">${html}</div></div>`;root.querySelector('.modal').addEventListener('click',e=>e.stopPropagation())}
function closeModal(){document.getElementById('modalRoot').innerHTML=''}
function openComments(id){const p=state.posts.find(x=>x.id===id);if(!p)return;state.commentsPost=id;showModal(`<button class="modal-close" data-do="closeModal">×</button><h2>Conversation</h2><div class="comment-list">${(p.comments||[]).map((c,i)=>`<div class="comment-row"><span><b>${esc(c.by.name||c.by)}</b> ${esc(c.text)}</span><button class="text-link" data-do="commentLike" data-id="${id}" data-i="${i}">♡ ${c.likes||0}</button><button class="text-link" data-do="reply" data-name="${esc(c.by.name||c.by)}">Reply</button></div>`).join('')||'<p class="helper-note">Be the first to comment.</p>'}</div><form id="commentForm" class="chat-compose"><input id="commentInput" placeholder="Add a kind comment..." maxlength="400" required><button class="button-primary">Post</button></form>`)}
