function bind(){document.querySelectorAll('[data-page]').forEach(x=>x.onclick=()=>setPage(x.dataset.page));document.getElementById('themeToggle')?.addEventListener('click',toggleTheme);document.getElementById('topTheme')?.addEventListener('click',toggleTheme);document.querySelector('.search-trigger')?.addEventListener('click',()=>{setPage('explore');setTimeout(()=>document.getElementById('searchInput')?.focus(),0)});document.querySelectorAll('[data-do]').forEach(el=>el.addEventListener('click',handleClick));document.getElementById('searchInput')?.addEventListener('input',e=>{state.search=e.target.value;const pos=e.target.selectionStart;render();const i=document.getElementById('searchInput');i.focus();i.setSelectionRange(pos,pos)});document.getElementById('postFile')?.addEventListener('change',previewFile);document.getElementById('postForm')?.addEventListener('submit',submitPost);document.getElementById('chatForm')?.addEventListener('submit',sendMessage);document.getElementById('channelForm')?.addEventListener('submit',sendChannel);document.getElementById('commentForm')?.addEventListener('submit',submitComment);document.getElementById('profileForm')?.addEventListener('submit',saveProfile);document.getElementById('authForm')?.addEventListener('submit',submitAuth);document.getElementById('reelStage')?.addEventListener('touchstart',e=>window._touchY=e.touches[0].clientY,{passive:true});document.getElementById('reelStage')?.addEventListener('touchend',e=>{const d=window._touchY-e.changedTouches[0].clientY;if(Math.abs(d)>40)moveReel(d>0?1:-1)},{passive:true});document.getElementById('reelPlay')?.addEventListener('click',()=>toast('Sample preview clip — video playback is not available.'))}
function handleClick(e){const el=e.currentTarget,act=el.dataset.do,id=el.dataset.id,p=state.posts.find(x=>x.id===id);if(act==='closeModal'){closeModal();return}if(act==='follow'){const h=el.dataset.h,idx=state.following.indexOf(h);if(idx<0){state.following.push(h);const person=people.find(x=>x.handle===h);notify('follow',person||state.profile,'started following you');toast(`Following @${h}`)}else{state.following.splice(idx,1);toast(`Unfollowed @${h}`)}persist();render()}else if(act==='create')setPage('create');else if(act==='photo'||act==='video'){state.postType=act;setPage('create')}else if(act==='filter'){state.feedFilter=state.feedFilter==='For you'?'Following':'For you';render()}else if(act==='exploreFilter'){state.exploreFilter=el.dataset.val;render()}else if(act==='type'){state.postType=el.dataset.val;render()}else if(act==='like'){state.liked[id]=!state.liked[id];if(state.liked[id])notify('like',p?.author,'liked your post');persist();render()}else if(act==='dislike'){state.disliked[id]=!state.disliked[id];state.liked[id]=false;persist();render()}else if(act==='comments')openComments(id);else if(act==='share'){const url=location.href.split('#')[0]+'#post-'+id;if(navigator.share)navigator.share({title:'Hnmgram',url}).catch(()=>{});else if(navigator.clipboard)navigator.clipboard.writeText(url).then(()=>toast('Post link copied')).catch(()=>toast('Share link: '+url));else toast('Share link: '+url)}else if(act==='reshare'&&p){state.posts.unshift({...p,id:'share-'+Date.now(),author:state.profile,time:'just now',reshared:true,sample:false});notify('reshare',p.author,'reshared your post');persist();render();toast('Post reshared')}else if(act==='menu')toast('Post options: this is sample content.');else if(act==='chatTab'){state.messageTab=el.dataset.val;render()}else if(act==='channelTab'){state.activeChannel=Number(el.dataset.i);state.channelSection='chat';render()}else if(act==='channelSection'){state.channelSection=el.dataset.val;render()}else if(act==='newChannel')newChannel();else if(act==='profileTab'){state.profileTab=el.dataset.val;render()}else if(act==='editProfile')editProfile();else if(act==='commentLike'){const c=p.comments[Number(el.dataset.i)];c.likes=(c.likes||0)+1;persist();openComments(id)}else if(act==='reply'){document.getElementById('commentInput').value=`@${el.dataset.name} `;document.getElementById('commentInput').focus()}else if(act==='readAll'){state.notifications.forEach(n=>n.read=true);persist();render()}else if(act==='auth')authModal('signup');else if(act==='authMode')authModal(el.dataset.val);else if(act==='social')toast(`${el.dataset.val} sign-in needs verified provider setup; no credentials were sent.`);else if(act==='addStory')toast('Add a story from Create post — story publishing is preview-only.');else if(act==='story'){const person=people[Number(el.dataset.i)];showModal(`<button class="modal-close" data-do="closeModal">×</button><div class="story-preview">${avatar(person.pic)}<h2>${esc(person.name)}’s story</h2><p>Sample story preview · This content is illustrative.</p><img src="${img('photo-1470252649378-9c29740c9fa8',800,700)}" alt="Sample story"></div>`)}else if(act==='reelLike'){toast('Liked this sample reel');}else if(act==='reply'){} }
function moveReel(step){state.reelIndex=(state.reelIndex+step+reelsData.length)%reelsData.length;render()}
function previewFile(e){const f=e.target.files[0];if(!f)return;const wrap=document.getElementById('previewWrap');if(state.postType==='video'){if(f.size>10*1048576){toast('Video is over the 10 MB per-video limit.');e.target.value='';return}if(state.videoBytes+f.size>100*1048576){toast('This video exceeds your remaining 100 MB total storage.');e.target.value='';return}}if(state.postType==='photo'&&!f.type.startsWith('image/')){toast('Choose an image file.');e.target.value='';return}if(state.postType==='video'&&!f.type.startsWith('video/')){toast('Choose a video file.');e.target.value='';return}state.pendingFile=f;const url=URL.createObjectURL(f);state.pendingUrl=url;if(wrap)wrap.innerHTML=state.postType==='photo'?`<img class="upload-preview" src="${url}" alt="Selected photo preview">`:`<video class="upload-preview" src="${url}" controls></video>`;document.getElementById('fileHint').textContent=`${f.name} · ${fmt(f.size)}`}
function submitPost(e){e.preventDefault();const text=document.getElementById('postText').value.trim(),f=state.pendingFile;if(!text&&!f){toast('Add some text or choose a photo/video first.');return}if(state.postType!=='text'&&!f){toast('Choose a file to attach.');return}const item={id:'p'+Date.now(),author:{...state.profile},text,likes:0,comments:[],time:'just now',sample:false};if(f){item.mediaType=state.postType;item.mediaKey=true;state.mediaUrls[item.id]=state.pendingUrl;if(state.postType==='photo')item.image=state.pendingUrl;else{item.video=state.pendingUrl;state.videoBytes+=f.size}}state.posts.unshift(item);state.pendingFile=null;state.pendingUrl=null;persist();state.page='home';render();toast('Your post was added to this browser preview.')}
function sendMessage(e){e.preventDefault();const input=document.getElementById('chatInput'),text=input.value.trim();if(!text)return;const key=state.messageTab;state.messages[key]??=[];state.messages[key].push({by:state.profile.name,text,time:new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})});persist();render();document.getElementById('chatMessages')?.scrollTo(0,99999)}
function sendChannel(e){e.preventDefault();const c=state.channels[state.activeChannel],input=document.getElementById('channelInput'),text=input.value.trim();if(!c||!text)return;c.chat??=[];c.chat.push({by:state.profile.name,text,time:new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})});persist();render();document.getElementById('channelMessages')?.scrollTo(0,99999)}
