function newChannel(){showModal(`<button class="modal-close" data-do="closeModal">×</button><h2>Create a channel</h2><form id="channelCreateForm" class="stack-form"><label>Channel name<input name="name" maxlength="40" required placeholder="e.g. Sunday Gardeners"></label><label>What’s it about?<textarea name="about" maxlength="120" required placeholder="A few words about your community"></textarea></label><label>Emoji<input name="emoji" maxlength="4" value="🌱"></label><button class="button-primary">Create channel</button></form>`);bindModal()}
