function submitComment(e){e.preventDefault();const p=state.posts.find(x=>x.id===state.commentsPost),input=document.getElementById('commentInput'),text=input.value.trim();if(!p||!text)return;p.comments??=[];p.comments.push({by:{...state.profile},text,likes:0});notify('comment',p.author,'commented on your post');persist();openComments(p.id)}
