function bindModal(){document.querySelectorAll('#modalRoot [data-do]').forEach(el=>el.addEventListener('click',handleClick));document.getElementById('profileForm')?.addEventListener('submit',saveProfile);document.getElementById('authForm')?.addEventListener('submit',submitAuth);document.getElementById('commentForm')?.addEventListener('submit',submitComment);document.getElementById('channelCreateForm')?.addEventListener('submit',e=>{e.preventDefault();const d=new FormData(e.target);state.channels.push({name:String(d.get('name')).trim(),about:String(d.get('about')).trim(),emoji:String(d.get('emoji')||'🌱'),members:1,chat:[]});state.activeChannel=state.channels.length-1;state.channelSection='chat';persist();closeModal();state.page='channels';render();toast('Channel created in this browser preview.')})}
function init(){render();if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./sw.js').catch(()=>{});document.addEventListener('keydown',e=>{if(state.page==='reels'&&e.key==='ArrowDown')moveReel(1);if(state.page==='reels'&&e.key==='ArrowUp')moveReel(-1);if(e.key==='Escape')closeModal()})}
