2: const people=[{name:'Maya Chen',handle:'mayainmotion',pic:img('photo-1531123897727-8f129e1688ce',100,100)},{name:'Theo Brooks',handle:'theobrooks',pic:img('photo-1500648767791-00dcc994a43e',100,100)},{name:'Nina Flores',handle:'ninaflores',pic:img('photo-1534528741775-53994a69daeb',100,100)},{name:'Oliver Park',handle:'oliverpark',pic:img('photo-1506794778202-cad84cf45f1d',100,100)},{name:'Amara Okafor',handle:'amara.o',pic:img('photo-1534751516642-a1af1ef26a56',100,100)},{name:'Luca Moretti',handle:'lucamoretti',pic:img('photo-1507003211169-0a1dd7228f2d',100,100)}];
3: const me={name:'Alex Morgan',handle:'alexmorgan',pic:img('photo-1534528741775-53994a69daeb',100,100),bio:'Collecting little moments 🌿 | design, slow travel & good coffee',place:'Portland, OR'};
4: const seed=[{id:'p1',author:people[0],text:'A slow morning, a warm pastel de nata, and absolutely nowhere to be. Lisbon, you have my whole heart ☀️',image:img('photo-1470252649378-9c29740c9fa8',1000,760),likes:248,comments:[{by:people[1],text:'Adding this to my someday list ✨',likes:12},{by:people[2],text:'That light is unreal!',likes:4}],time:'18 min',sample:true},{id:'p2',author:people[1],text:'Tiny reminder: you don’t have to have it all figured out to take the next step. 🌱',likes:87,comments:[{by:people[4],text:'Needed to hear this today.',likes:8}],time:'1 hr',sample:true},{id:'p3',author:people[3],text:'The city before it wakes up. Just me, my camera, and the last of the blue hour.',image:img('photo-1519501025264-65ba15a82390',1000,760),likes:512,comments:[{by:people[0],text:'The colors! 😍',likes:16}],time:'3 hr',sample:true},{id:'p4',author:people[4],text:'Sunday table, extra chairs, and enough jollof for everyone. That’s the whole plan. ❤️',image:img('photo-1547592180-85f173990554',1000,760),likes:174,comments:[],time:'5 hr',sample:true}];
5: const get=(k,d)=>{try{return JSON.parse(localStorage.getItem('hnm-'+k))??d}catch{return d}};
6: const state={page:'home',theme:localStorage.getItem('hnm-theme')||'light',posts:get('posts',seed),following:get('following',[people[0].handle,people[2].handle]),notifications:get('notifs',[]),commentsPost:null,profileTab:'posts',messageTab:'general',activeChannel:0,channelSection:'chat',messages:get('messages',{general:[{by:'Maya Chen',text:'Good morning, Hnmgram ☀️',time:'9:14'},{by:'Theo Brooks',text:'Anyone have a favorite tiny coffee shop in Lisbon?',time:'9:20'}]}),channels:get('channels',[{name:'Little Green Things',about:'Plant people, sharing what’s growing 🌱',members:128,emoji:'🌿',chat:[]},{name:'Weekend Frames',about:'A cozy corner for photo walks and film.',members:84,emoji:'📷',chat:[]}]),search:'',exploreFilter:'For you',feedFilter:'For you',postType:'text',videoBytes:Number(localStorage.getItem('hnm-video-bytes')||0),liked:get('liked',{}),disliked:get('disliked',{}),profile:get('profile',me),users:get('users',[]),signedIn:localStorage.getItem('hnm-user')||'',mediaUrls:{},reelIndex:0,storyIndex:null};
7: function persist(){for(const k of ['posts','following','messages','channels','profile','users','liked','disliked'])localStorage.setItem('hnm-'+k,JSON.stringify(state[k]));localStorage.setItem('hnm-notifs',JSON.stringify(state.notifications));localStorage.setItem('hnm-video-bytes',state.videoBytes)}
8: const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const fmt=n=>n<1024?`${n} B`:`${(n/1048576).toFixed(1)} MB`;
9: function toast(m){const r=document.getElementById('toastRoot');r.innerHTML=`<div class="toast">${esc(m)}</div>`;setTimeout(()=>r.innerHTML='',3000)}
10: function avatar(url,cls='avatar'){return `<img class="${cls}" src="${url}" alt="">`}
11: function notify(type,person,text){state.notifications.unshift({type,person,text,time:'just now',read:false});persist()}
12: function setPage(p){state.page=p;if(p==='create')state.postType='text';render()}
13: function toggleTheme(){state.theme=state.theme==='light'?'dark':'light';localStorage.setItem('hnm-theme',state.theme);render()}
14: const pageNames={home:'Home',explore:'Explore',reels:'Reels',create:'Create post',notifications:'Notifications',messages:'Messages',channels:'Channels',profile:'Your profile'};
15: function render(){document.documentElement.dataset.theme=state.theme;const title=document.getElementById('pageTitle');if(title)title.textContent=pageNames[state.page]||'Home';document.querySelectorAll('[data-page]').forEach(x=>x.classList.toggle('active',x.dataset.page===state.page));document.getElementById('pageContent').innerHTML=({home,explore,reels:reelsView,create:createView,notifications:notifs,messages,channels,profile}[state.page]||home)();document.getElementById('rightRail').innerHTML=state.page==='home'?rail():'';syncProfileChrome();bind()}
16: function syncProfileChrome(){document.querySelectorAll('.profile-shortcut b').forEach(e=>e.textContent=state.profile.name);document.querySelectorAll('.profile-shortcut small').forEach(e=>e.textContent='@'+state.profile.handle);document.querySelectorAll('.profile-shortcut .avatar,.top-avatar img').forEach(e=>e.src=state.profile.pic)}
17: function rail(){return `<div class="rail-card"><h3>People to know</h3>${people.filter(p=>!state.following.includes(p.handle)).slice(0,3).map(p=>`<div class="user-row">${avatar(p.pic)}<span class="user-info"><strong>${esc(p.name)}</strong><small>@${esc(p.handle)}</small></span><button class="follow-button" data-do="follow" data-h="${p.handle}">Follow</button></div>`).join('')}</div><div class="rail-card"><h3>Your space, your pace 🌱</h3><div style="font-size:11px;color:var(--muted);line-height:1.6">A little more connection, a little less noise. Follow the people who make your day brighter.</div></div><div class="rail-footer">About · Community · Privacy · Guidelines<br>© 2025 Hnmgram <span class="sample-badge">PREVIEW CONTENT</span></div>`}
18: function stories(){return `<div class="stories"><button class="story add" data-do="addStory"><span class="story-ring">＋</span><span>Your story</span></button>${people.filter(p=>state.following.includes(p.handle)).map((p,i)=>`<button class="story" data-do="story" data-i="${people.indexOf(p)}"><span class="story-ring ${i===1?'seen':''}">${avatar(p.pic,'')}</span><span>${esc(p.name.split(' ')[0])}</span></button>`).join('')}</div>`}
19: function post(p){const a=p.author||state.profile,src=p.mediaKey?state.mediaUrls[p.id]:null;let media=p.video||p.mediaType==='video'?`<video class="post-media" controls playsinline loop src="${src||p.video||''}"></video>`:p.image||p.mediaType==='photo'?`<img class="post-media" src="${src||p.image||''}" alt="Post from ${esc(a.name)}">`:'';return `<article class="post-card"><div class="post-head">${avatar(a.pic)}<div class="post-author"><strong>${esc(a.name)} ${p.sample?'<span class="sample-badge">SAMPLE</span>':''}</strong><span>@${esc(a.handle)} · ${esc(p.time||'now')}</span></div><button class="post-menu" data-do="menu" data-id="${p.id}" aria-label="Post options">•••</button></div>${p.text?`<p class="post-copy">${esc(p.text)}</p>`:''}${media}<div class="post-actions"><button class="action-button ${state.liked[p.id]?'selected':''}" data-do="like" data-id="${p.id}">♡ <span>${p.likes+(state.liked[p.id]?1:0)}</span></button><button class="action-button disliked ${state.disliked[p.id]?'selected':''}" data-do="dislike" data-id="${p.id}">☟</button><button class="action-button" data-do="comments" data-id="${p.id}">▢ <span>${p.comments?.length||0}</span></button><button class="action-button" data-do="share" data-id="${p.id}">↗</button><button class="action-button" data-do="reshare" data-id="${p.id}">⟳</button></div><div class="post-likes">Liked by <b>${p.likes+(state.liked[p.id]?1:0)} people</b> · <button class="text-link" style="padding:0" data-do="comments" data-id="${p.id}">View all ${p.comments?.length||0} comments</button></div></article>`}
20: function home(){let list=state.posts;if(state.feedFilter==='Following')list=list.filter(p=>p.author?.handle===state.profile.handle||state.following.includes(p.author?.handle));return `<div class="section-heading"><div><h2>Your little corner of the world</h2><p>Good things are happening around you.</p></div><button class="text-link" data-do="filter">${state.feedFilter}⌄</button></div>${stories()}<div class="feed-compose">${avatar(state.profile.pic)}<button class="compose-prompt" data-do="create">What’s on your mind, ${esc(state.profile.name.split(' ')[0])}?</button><div class="compose-tools"><button data-do="photo">▧</button><button data-do="video">▷</button></div></div>${list.map(post).join('')}`}
21: function explore(){const items=state.posts.filter(p=>!state.search||`${p.text} ${p.author?.name}`.toLowerCase().includes(state.search.toLowerCase()));return `<div class="page-banner"><div><h1>Find your next favorite</h1><p>Fresh ideas, kind people, good things.</p></div></div><label class="search-box"><span>⌕</span><input id="searchInput" placeholder="Search people, places, things..." value="${esc(state.search)}"></label><div class="tag-row">${['For you','People','Places','Photography','Food','Outdoors','Design'].map(x=>`<button class="tag-chip ${state.exploreFilter===x?'active':''}" data-do="exploreFilter" data-val="${x}">${x}</button>`).join('')}</div><div class="section-heading"><h2>${state.exploreFilter==='People'?'People you might love':'A little inspiration'}</h2><span class="sample-badge">SAMPLE PREVIEW</span></div>${state.exploreFilter==='People'?`<div class="rail-card">${people.map(p=>`<div class="user-row">${avatar(p.pic)}<span class="user-info"><strong>${esc(p.name)}</strong><small>@${p.handle}</small></span><button class="follow-button" data-do="follow" data-h="${p.handle}">${state.following.includes(p.handle)?'Following':'Follow'}</button></div>`).join('')}</div>`:`<div class="explore-grid">${items.map((p,i)=>`<button class="explore-tile" data-do="comments" data-id="${p.id}"><img src="${p.image||people[i%people.length].pic}" alt="Explore post"><span class="tile-overlay">♡ ${p.likes} · ${esc(p.author?.name||'You')}</span></button>`).join('')||'<p class="helper-note">No posts found. Try another search.</p>'}</div>`}`}
22: const reelsData=[{user:people[4],image:img('photo-1470252649378-9c29740c9fa8',800,1200),caption:'A little golden hour magic ✨ #slowdays'},{user:people[2],image:img('photo-1500530855697-b586d89ba3ee',800,1200),caption:'Took the long way home. Always take the long way. 🌿'},{user:people[0],image:img('photo-1518837695005-2083093ee35b',800,1200),caption:'Ocean air and no plans. My kind of weekend 🌊'}];
23: function reelsView(){const r=reelsData[state.reelIndex%reelsData.length];return `<div class="page-banner"><div><h1>Reels</h1><p>Little moments, on repeat.</p></div><span class="account-pill">Swipe to explore ↑↓</span></div><div class="reel-stage" id="reelStage"><img src="${r.image}" alt="Vertical reel by ${r.user.name}"><div class="reel-shade"></div><button class="reel-play" id="reelPlay">▶</button><span class="video-label">PREVIEW CLIP</span><div class="reel-meta"><strong>@${r.user.handle}</strong><p>${r.caption}</p><button class="button-primary" data-do="follow" data-h="${r.user.handle}">＋ Follow</button></div><div class="reel-actions"><button data-do="reelLike">♡</button><button data-do="comments" data-id="p1">▢</button><button data-do="share" data-id="p1">↗</button></div></div><p class="reel-hint">Tap to play · swipe or use ↑ ↓ to see another</p>`}
24: function createView(){return `<div class="page-banner"><div><h1>Create a post</h1><p>Share a moment with your people.</p></div></div><form class="form-card" id="postForm"><h2>Your story, your way</h2><p>Text, photos, and videos are all welcome here.</p><div class="tag-row">${['text','photo','video'].map(t=>`<button type="button" class="tag-chip ${state.postType===t?'active':''}" data-do="type" data-val="${t}">${t==='text'?'✎ Text':t==='photo'?'▧ Photo':'▷ Video'}</button>`).join('')}</div><label class="form-label">Say something</label><textarea class="text-area" id="postText" placeholder="What would you like to share?" maxlength="700"></textarea>${state.postType!=='text'?`<label class="upload-zone">Choose a ${state.postType}<input id="postFile" type="file" accept="${state.postType==='photo'?'image/*':'video/*'}"><span id="fileHint">${state.postType==='video'?`Maximum 10 MB per video · ${fmt(state.videoBytes)} used of 100 MB total`:'JPG, PNG, GIF or WebP'}</span></label>`:''}${state.postType==='video'?`<div class="upload-progress"><div class="progress-label"><span>Hnmgram video storage</span><b>${fmt(state.videoBytes)} used · ${fmt(Math.max(0,104857600-state.videoBytes))} remaining</b></div><div class="progress-track"><span style="width:${Math.min(100,state.videoBytes/1048576)}%"></span></div></div><p class="helper-note">Videos over 10 MB or beyond the 100 MB total storage limit cannot be added.</p>`:''}<div id="previewWrap"></div><button class="button-primary" style="width:100%;margin-top:8px;padding:12px">Share with your people ↗</button></form>`}
25: function notifs(){if(!state.notifications.length)return `<div class="page-banner"><div><h1>Your activity</h1><p>Little moments of connection.</p></div></div><div class="empty-state">You’re all caught up 🌿<br><small>New likes, follows, and replies will show here.</small></div>`;return `<div class="page-banner"><div><h1>Your activity</h1><p>Little moments of connection.</p></div><button class="text-link" data-do="readAll">Mark all read</button></div><div class="rail-card">${state.notifications.map(n=>`<div class="user-row notification-row ${n.read?'read':''}">${avatar(n.person?.pic||people[0].pic)}<span class="user-info"><strong>${esc(n.person?.name||'Hnmgram')}</strong><small>${esc(n.text)} · ${esc(n.time)}</small></span>${n.read?'':'<span class="unread-dot"></span>'}</div>`).join('')}</div>`}
26: function chatData(){return state.messageTab==='general'?state.messages.general:(state.messages[state.messageTab]||[])}
27: function messages(){const tabs=[['general','General chat'],...people.map(p=>[p.handle,p.name])],data=chatData();return `<div class="page-banner"><div><h1>Messages</h1><p>Say hello, share a little kindness.</p></div></div><div class="chat-layout"><aside class="chat-list">${tabs.map(([id,n])=>`<button class="chat-tab ${state.messageTab===id?'active':''}" data-do="chatTab" data-val="${id}">${esc(n)}</button>`).join('')}</aside><section class="chat-room"><div class="chat-room-head"><strong>${state.messageTab==='general'?'Hnmgram community':esc(people.find(p=>p.handle===state.messageTab)?.name||state.messageTab)}</strong><small>${state.messageTab==='general'?'Shared preview chat':'Private message preview'}</small></div><div class="chat-messages" id="chatMessages">${data.map(m=>`<div class="chat-bubble ${m.by===state.profile.name?'mine':''}"><small>${esc(m.by)}</small><p>${esc(m.text)}</p><time>${esc(m.time)}</time></div>`).join('')||'<p class="helper-note">Start the conversation with a kind hello.</p>'}</div><form class="chat-compose" id="chatForm"><input id="chatInput" placeholder="Write a message..." maxlength="500" required><button class="button-primary">Send</button></form></section></div><p class="helper-note">Preview messages are stored only in this browser.</p>`}
28: function channels(){const c=state.channels[state.activeChannel]||state.channels[0];return `<div class="page-banner"><div><h1>Channels</h1><p>Find your people around the things you love.</p></div><button class="button-primary" data-do="newChannel">＋ Create channel</button></div><div class="channel-wrap"><aside class="channel-list">${state.channels.map((x,i)=>`<button class="channel-item ${i===state.activeChannel?'active':''}" data-do="channelTab" data-i="${i}"><span>${x.emoji}</span><b>${esc(x.name)}</b></button>`).join('')}</aside>${c?`<section class="channel-room"><div class="chat-room-head"><strong>${c.emoji} ${esc(c.name)}</strong><small>${esc(c.about)} · ${c.members} members</small></div><div class="tag-row"><button class="tag-chip ${state.channelSection==='chat'?'active':''}" data-do="channelSection" data-val="chat">Chat</button><button class="tag-chip ${state.channelSection==='videos'?'active':''}" data-do="channelSection" data-val="videos">Videos</button></div>${state.channelSection==='chat'?`<div class="chat-messages" id="channelMessages">${(c.chat||[]).map(m=>`<div class="chat-bubble ${m.by===state.profile.name?'mine':''}"><small>${esc(m.by)}</small><p>${esc(m.text)}</p><time>${esc(m.time)}</time></div>`).join('')||'<p class="helper-note">Be the first to say hello in this channel.</p>'}</div><form class="chat-compose" id="channelForm"><input id="channelInput" placeholder="Message this channel..." maxlength="500" required><button class="button-primary">Send</button></form>`:`<div class="channel-videos">${state.posts.filter(p=>p.mediaType==='video'||p.video).map(post).join('')||'<div class="empty-state">No videos here yet.<br><small>Videos you share will be available in channels.</small></div>'}</div>`}</section>`:'<div class="empty-state">Create your first channel.</div>'}</div><p class="helper-note">Channel activity is saved in this browser preview.</p>`}
29: function profile(){const mine=state.posts.filter(p=>p.author?.handle===state.profile.handle),shown=state.profileTab==='posts'?mine:state.profileTab==='videos'?mine.filter(p=>p.video||p.mediaType==='video'):[];return `<div class="profile-cover"><div class="profile-cover-art"></div>${avatar(state.profile.pic,'profile-avatar-large')}<button class="button-secondary profile-edit" data-do="editProfile">Edit profile</button></div><div class="profile-name-line"><div><h1>${esc(state.profile.name)}</h1><span>@${esc(state.profile.handle)}</span></div></div><p class="profile-bio">${esc(state.profile.bio||'Add a little about yourself.')}</p><p class="profile-bio">⌖ ${esc(state.profile.place||'Add your location')}</p><div class="profile-stats"><span><b>${mine.length}</b> posts</span><span><b>${state.following.length+18}</b> following</span><span><b>${12+state.notifications.length}</b> followers</span></div>${!state.signedIn?`<div class="account-pill">Preview mode · Your posts and profile are saved on this device. <button class="text-link" data-do="auth">Create account / Sign in</button></div>`:''}<div class="tag-row profile-tabs">${['posts','videos','about'].map(t=>`<button class="tag-chip ${state.profileTab===t?'active':''}" data-do="profileTab" data-val="${t}">${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</div>${state.profileTab==='about'?`<div class="rail-card"><h3>About ${esc(state.profile.name)}</h3><p>${esc(state.profile.bio||'No bio yet.')}</p><p>⌖ ${esc(state.profile.place||'Location not added')}</p></div>`:shown.length?shown.map(post).join(''):'<div class="empty-state">Your space is ready for its first post ✨<br><button class="button-primary" data-page="create">Create a post</button></div>'}`}
